def gcd(a: int, b: int) -> int:
    """Compute the greatest common divisor of a and b using Euclidean algorithm."""
    while b != 0:
        a, b = b, a % b
    return a

def lcm(a: int, b: int) -> int:
    """Compute the least common multiple of two positive integers."""
    if a <= 0 or b <= 0:
        raise ValueError("Both numbers must be positive integers.")
    return a * b // gcd(a, b)

# Example usage:
if __name__ == "__main__":
    print(lcm(4, 6))   # 12
    print(lcm(7, 5))   # 35
    print(lcm(12, 18)) # 36

def fibonacci(n: int) -> int:
    """
    Return the n-th Fibonacci number using recursion.
    Assumes n is a non-negative integer.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

def count_even(lst):
    """
    Returns the number of even elements in the given list using a lambda function.
    """
    # Filter even numbers using lambda, convert to list, and get its length
    return len(list(filter(lambda x: x % 2 == 0, lst)))

def max_sum_list(list_of_lists):
    """
    Returns the inner list from list_of_lists whose elements sum to the highest value.
    If list_of_lists is empty, returns None.
    """
    if not list_of_lists:
        return None
    return max(list_of_lists, key=sum)

def camel_to_snake(s: str) -> str:
    """
    Convert a camelCase string to snake_case.
    Handles empty strings, PascalCase, and consecutive uppercase.
    """
    if not s:
        return s

    result = []
    for i, ch in enumerate(s):
        if ch.isupper():
            if i > 0:  # Not the first character
                result.append('_')
            result.append(ch.lower())
        else:
            result.append(ch)
    return ''.join(result)


